function field(parent,label,value,onchange,type='text',options){const wrap=node('div');const name='field-'+crypto.randomUUID();const l=node('label',label);l.htmlFor=name;const input=node(type==='textarea'?'textarea':type==='select'?'select':'input');input.id=name;if(type!=='textarea'&&type!=='select')input.type=type;if(options)for(const [v,t]of options){const o=node('option',t);o.value=v;input.append(o);}input.value=value??'';let last=input.value,timer;const commit=()=>{clearTimeout(timer);if(input.value===last)return;last=input.value;run(()=>onchange(input.value));};input.onchange=commit;if(type==='text'||type==='textarea')input.oninput=()=>{clearTimeout(timer);timer=setTimeout(commit,700);};wrap.append(l,input);parent.append(wrap);return input;}
