$('#history').onclick=()=>run(async()=>{historyPage=1;await showHistory();});
async function showHistory(){message('Loading versions…');const start=await store.historyStart();const [commits,names]=await Promise.all([store.history(historyPage,start?.startedAt||''),store.labels()]);const revisions=commits.filter(r=>/^Church Studio: /.test(r.commit.message)&&r.sha!==start?.startSha);
 const loadVersion=async sha=>{const previous=await store.revision(sha);changed(()=>design=previous);selected='';options();drawTools();await renderPreview();$('#modal').close();message('Version loaded into your draft. Choose Publish to make it live again.');};
 modal('Versions',root=>{root.append(hint('Load a version into your draft, check it in the preview, then Publish to make it live. Newest first.'));
  if(!revisions.length&&historyPage===1)root.append(hint('No published versions yet. Each time you Publish, a named version is added here.'));
  for(const r of revisions){const card=node('section',undefined,'revision');let name=names[r.sha]||r.commit.message.replace(/^Church Studio: /,'').split('\n')[0];const input=field(card,'Version name',name,v=>name=v);input.maxLength=100;card.append(node('p',new Date(r.commit.author.date).toLocaleString()+' · '+(r.author?.login||r.commit.author.name)));card.append(row(button('Rename',async()=>{if(!name.trim())throw Error('Give this version a name.');await store.rename(r.sha,name);message('Version name saved.');}),button('Load this version',()=>loadVersion(r.sha),'primary')));root.append(card);}
  if(start?.startSha&&commits.length<20){const card=node('section',undefined,'revision original');card.append(node('h3','Original version'),node('p','The website as it was before Studio editing began'+(start.startedAt?' ('+new Date(start.startedAt).toLocaleDateString()+')':'')+'. You can always go back to this.'),row(button('Load original version',()=>loadVersion(start.startSha),'primary')));root.append(card);}
  if(historyPage>1||commits.length===20)root.append(row(button('← Newer',async()=>{if(historyPage>1){historyPage--;await showHistory();}}),button('Older →',async()=>{if(commits.length===20){historyPage++;await showHistory();}})));});message('Versions loaded.');}

function validateBeforePublish(){validateDesign(design);for(const item of design.content.moments||[]){if(!item.title?.trim()||!mediaUrl(item.url))throw Error('Each church moment needs a title and a photo or video.');if(item.type==='video'&&!/^data:video\/mp4;base64,/.test(item.url)&&!(/\.mp4(?:[?#].*)?$/i.test(item.url)))throw Error('Use a direct MP4 link for gallery videos, or upload an MP4 file.');}if(!design.content.settings.name.trim())throw Error('Add the church name before publishing.');for(const e of design.content.events||[]){if(!e.title?.trim()||!e.start||Number.isNaN(Date.parse(e.start)))throw Error('Each church event needs a title and a valid start date.');if(e.end&&(!(new Date(e.end)>new Date(e.start))))throw Error('Each event must end after it starts.');}if(design.content.settings.slideshowMode==='custom'&&!design.content.slides.length)throw Error('Add a photo slide or use church events for the homepage slideshow.');}
$('#publish').onclick=()=>run(()=>{validateBeforePublish();modal('Publish',root=>{let name='';const changedPages=Object.keys(design.pages).filter(p=>JSON.stringify(design.pages[p])!==JSON.stringify(published.pages[p]));root.append(node('p','Your current published design is already kept in GitHub history. This publishes a new named version, including its photos.'));root.append(node('p',(changedPages.length?'Pages changed: '+changedPages.map(p=>design.pages[p].label).join(', ')+'. ':'')+(JSON.stringify(design.theme)!==JSON.stringify(published.theme)?'Site theme changed. ':'')+(JSON.stringify(design.content)!==JSON.stringify(published.content)?'Church content changed. ':'')+(JSON.stringify(design.navigation)!==JSON.stringify(published.navigation)?'Navigation changed.':'')));const input=field(root,'Name this revision','',v=>name=v);input.placeholder='Example: October welcome update';input.maxLength=100;const submit=button('Publish this revision',async()=>{name=input.value;if(!name.trim())throw Error('Name this version so you can find it later.');if(busy)return;busy=true;submit.disabled=true;$('#modal-close').disabled=true;try{message('Saving your design and photos to GitHub…');const result=await store.publish(design,name,async clean=>{const pages={};for(const path of Object.keys(clean.pages)){let raw;if(clean.pages[path].custom){raw=(await template()).replaceAll('{{title}}',clean.pages[path].label.replace(/[<>]/g,'')).replaceAll('{{path}}',path);}else raw=await source(path);pages[path]=compilePage(raw,clean,path);}return pages;});design=result.design;published=clone(design);baselineHead=result.sha;dirty=false;undo=[];redo=[];sourceCache={};clearTimeout(autosaveTimer);localStorage.removeItem(draftKey());syncUndo();$('#modal').close();await renderPreview();message('Revision saved to GitHub. The website is rebuilding.');void monitorDeployment(result.sha);}finally{busy=false;submit.disabled=false;$('#modal-close').disabled=false;}},'primary');root.append(submit,hint('Only public website content is published. Do not put private prayer requests, personal records or passwords into a page.'));});});
async function monitorDeployment(sha){for(let i=0;i<18;i++){await new Promise(r=>setTimeout(r,10000));if(!store.user)return;try{const deployment=await store.deployment(sha);if(deployment?.status==='completed'){message(deployment.conclusion==='success'?'Published successfully. Your named revision is live.':'GitHub saved the revision, but deployment did not succeed. Check the repository Actions page.',deployment.conclusion!=='success');return;}}catch{message('Revision saved to GitHub. Publishing progress is unavailable; check the live website or GitHub Actions.');return;}}message('Revision saved. GitHub is still publishing or has not reported a deployment. Check GitHub Actions before assuming it is live.');}


function drawMoments(){
 const items=design.content.moments ||= [];
 tools.append(hint('Add real photos and short MP4 videos. Captions tell the story; categories help visitors explore. Video uploads can be up to 6 MB. Larger videos need a direct, publicly playable MP4 link.'));
 items.forEach((item,index)=>{const card=node('section',undefined,'content-card');card.append(node('h3',item.title||'New moment'));
 field(card,'Photo or video',item.type||'photo',v=>{changed(()=>item.type=v);drawTools();},'select',[['photo','Photo'],['video','Video (MP4)'],['youtube','YouTube video link']]);
 field(card,'Category',item.category||'gatherings',v=>changed(()=>item.category=v),'select',[['events','Events & outreach'],['gatherings','Church gatherings'],['members','Member moments']]);
 field(card,'Event album name (leave blank for everyday church life)',item.album||'',v=>changed(()=>{item.album=v.trim();item.albumId=v.trim()?v.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-'):'';}));
 field(card,'Title',item.title,v=>changed(()=>item.title=v));field(card,'Tell the story',item.text,v=>changed(()=>item.text=v),'textarea');field(card,'Date (optional)',item.date||'',v=>changed(()=>item.date=v),'date');
 if(item.type==='video'){
 field(card,'Direct MP4 video link',item.url,v=>changed(()=>item.url=v));const input=node('input');input.type='file';input.accept='video/mp4';input.hidden=true;
 input.onchange=()=>run(async()=>{const file=input.files[0];if(!file)return;if(file.size>6*1024*1024)throw Error('Choose an MP4 smaller than 6 MB, or enter a direct MP4 link.');if(file.type!=='video/mp4')throw Error('Choose an MP4 video.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Unable to read this video.'));r.readAsDataURL(file);});changed(()=>item.url=data);message('Video added to your draft. Publish to save it on the website.');});
 card.append(input,button('Upload short MP4 video',()=>input.click()));imageControl(card,'Cover photo',item.image,v=>changed(()=>item.image=v));field(card,'Does this video have sound?',item.silent?'silent':'sound',v=>changed(()=>item.silent=v==='silent'),'select',[['sound','Has sound'],['silent','No audio']]);field(card,'Describe what happens in the video',item.accessibility||'',v=>changed(()=>item.accessibility=v),'textarea');
 }else if(item.type==='youtube'){field(card,'YouTube video link',item.url,v=>changed(()=>item.url=v));imageControl(card,'Video cover photo',item.image,v=>changed(()=>item.image=v));}else{imageControl(card,'Photo',item.url,v=>changed(()=>item.url=v));field(card,'Describe this photo',item.alt||'',v=>changed(()=>item.alt=v));}
 card.append(row(button('Move up',()=>{if(index===0)return;changed(()=>[items[index-1],items[index]]=[items[index],items[index-1]]);drawTools();}),button('Remove moment',()=>{changed(()=>items.splice(index,1));drawTools();},'danger')));tools.append(card);
 });tools.append(button('＋ Add a church moment',()=>{changed(()=>items.push({id:'moment-'+crypto.randomUUID(),type:'photo',category:'gatherings',title:'New church moment',text:'',url:'',alt:''}));drawTools();},'primary'));
}
